#include <stdlib.h>
#include <grrlib.h>
#include <wiiuse/wpad.h>

// Generated by bin2o from ../data/Bagel.jpg
#include "Bagel_jpg.h"

int main(int argc, char **argv) {
	// Initialise the graphics system and the controllers
	GRRLIB_Init();
	WPAD_Init();

	// Load the embedded JPEG into a texture
	GRRLIB_texImg *bagel = GRRLIB_LoadTexture(Bagel_jpg);

	while (SYS_MainLoop()) {
		WPAD_ScanPads();

		// Exit back to the loader when HOME is pressed
		if (WPAD_ButtonsDown(0) & WPAD_BUTTON_HOME) break;

		// Draw the bagel centered on screen
		if (bagel) {
			f32 x = ((int)rmode->fbWidth   - (int)bagel->w) / 2.0f;
			f32 y = ((int)rmode->efbHeight - (int)bagel->h) / 2.0f;
			GRRLIB_DrawImg(x, y, bagel, 0, 1, 1, 0xFFFFFFFF);
		}

		GRRLIB_Render();
	}

	// Free resources and shut down GRRLIB
	GRRLIB_FreeTexture(bagel);
	GRRLIB_Exit();

	exit(0);
}
